import sys
T = sys.argv[1]
def rep(path, pairs):
    p = f"{T}/{path}"; s = open(p).read()
    for old, new in pairs:
        n = s.count(old); assert n == 1, (path, n, old[:100])
        s = s.replace(old, new)
    open(p, 'w').write(s)

